package ec.edu.unl.sec.selfassessment.api;
import ec.edu.unl.sec.selfassessment.application.*;import ec.edu.unl.sec.selfassessment.domain.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/processes/{processId}/assignments")public class ProcessAssignmentController{private final ProcessAssignmentService service;public ProcessAssignmentController(ProcessAssignmentService service){this.service=service;}@GetMapping public List<ProcessAssignment> list(@PathVariable UUID processId){return service.list(processId);}@PostMapping public ResponseEntity<ProcessAssignment> assign(@PathVariable UUID processId,@RequestHeader("If-Match")String match,@Valid @RequestBody Command b,HttpServletRequest r){var a=service.assign(processId,SelfAssessmentController.rev(match),b.indicatorId(),b.identityId(),b.function(),b.validFrom(),b.validTo(),b.reason(),SelfAssessmentController.correlation(r));return ResponseEntity.created(URI.create("/api/v1/processes/"+processId+"/assignments/"+a.id())).body(a);}public record Command(@NotNull UUID indicatorId,@NotNull UUID identityId,@NotNull ProcessAssignment.Function function,@NotNull Instant validFrom,@NotNull Instant validTo,String reason){}}
